@RunWith(RobolectricTestRunner.class) @Config(sdk=33,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class SketchFocusedPaintMeshTest {
 interface Checked{void run()throws Exception;}
 void worker(Checked work)throws Exception{ExecutorService pool=Executors.newSingleThreadExecutor();try{pool.submit(()->{try{work.run();return null;}catch(Exception error){throw new RuntimeException(error);}}).get(90,TimeUnit.SECONDS);}finally{pool.shutdownNow();}}
 Context context(){return RuntimeEnvironment.getApplication();}
 JSONObject load(String id)throws Exception{return SketchPaintMeshTest.load(context(),id);}
 JSONObject fixture()throws Exception{
  String id="focused_"+java.util.UUID.randomUUID();SketchEditOps.execute(context(),"sketch_create",new JSONObject().put("sketchId",id).put("operationId","create").put("width",256).put("height",512).put("frameCount",8).put("background","#00000000"));
  SketchPaintMeshTest.edit(context(),id,1,"cel",new JSONArray().put(new JSONObject().put("type","add_paint_cel").put("objectId","paint").put("layerId","layer_1").put("exposure",8)));
  JSONObject brush=new JSONObject().put("mode","paint").put("color","#7F204060").put("sizePx",48).put("hardness",1).put("opacity",1).put("flow",1).put("pressure",false);
  SketchPaintMeshTest.edit(context(),id,2,"stroke",new JSONArray().put(new JSONObject().put("type","paint_stroke").put("objectId","paint").put("strokeId","pigment").put("points",new JSONArray("[[.7,.35,1],[.7,.52,1]]")).put("brush",brush)));
  brush.put("mode","erase").put("sizePx",16);SketchPaintMeshTest.edit(context(),id,3,"hole",new JSONArray().put(new JSONObject().put("type","paint_stroke").put("objectId","paint").put("strokeId","hole").put("points",new JSONArray("[[.7,.44,1]]")).put("brush",brush)));return load(id);
 }
 JSONObject prepare(JSONObject document,Object focus)throws Exception{JSONObject args=new JSONObject().put("sketchId",document.getString("id")).put("expectedRevision",document.getLong("revision")).put("objectId","paint").put("columns",8).put("rows",16);if(focus!=null)args.put("focusToInk",focus);return SketchPaintMeshPrepare.prepare(context(),args);}
 @Test public void preparationIsReadOnlyStrictBoundedAndSourceHashRetaining()throws Exception{worker(()->{
  JSONObject document=fixture();String before=SketchDocument.canonical(document);JSONObject result=prepare(document,true),mesh=result.getJSONObject("operation").getJSONObject("patch").getJSONObject("paintMesh");assertEquals("4.9.8",result.getString("minimumNativeVersion"));assertFalse(result.getBoolean("sourceModified"));assertEquals(before,SketchDocument.canonical(load(document.getString("id"))));assertEquals(SketchDocument.object(document,"paint").getJSONObject("paint").getString("sha256"),result.getString("sourcePaintSha256"));JSONArray rect=mesh.getJSONArray("sourceRect");assertTrue(rect.getInt(0)>120);assertTrue(rect.getInt(2)<230);assertTrue(rect.getInt(1)>120);assertTrue(rect.getInt(3)<310);JSONObject paint=SketchDocument.copy(SketchDocument.object(document,"paint")).put("paintMesh",mesh);assertTrue(SketchPaintMesh.regularAt(paint,0));assertArrayEquals(new int[]{0,153},SketchPaintMesh.validate(paint,8));
  assertFalse(prepare(document,false).getJSONObject("operation").getJSONObject("patch").getJSONObject("paintMesh").has("sourceRect"));assertEquals("4.9.8",prepare(document,false).getString("minimumNativeVersion"));assertEquals("4.9.5",prepare(document,null).getString("minimumNativeVersion"));
  for(Object invalid:new Object[]{0,1,"true",JSONObject.NULL})assertThrows(IllegalArgumentException.class,()->prepare(document,invalid));
  Thread.currentThread().interrupt();try{assertThrows(java.io.InterruptedIOException.class,()->prepare(document,true));}finally{Thread.interrupted();}
 });}
 @Test public void regularFocusedGridIsRgbaNeutralUnderRotationOpacityAndCachedSampling()throws Exception{
  final SketchFrameRenderer[] renderers=new SketchFrameRenderer[2];java.io.File evidence=new java.io.File("build/native-focused-mesh-neutrality/"+java.util.UUID.randomUUID());assertTrue(evidence.mkdirs());
  try{worker(()->{JSONObject plain=fixture(),grid=SketchDocument.copy(plain),mesh=prepare(plain,true).getJSONObject("operation").getJSONObject("patch").getJSONObject("paintMesh");SketchDocument.object(grid,"paint").put("paintMesh",mesh);
   for(JSONObject d:new JSONObject[]{plain,grid}){SketchEditOps.apply(d,new JSONObject().put("type","set_transform").put("objectId","paint").put("transform",new JSONObject().put("rotation",27).put("anchorX",.47).put("anchorY",.63).put("x",-.03).put("y",.06).put("opacity",.73)));SketchEditOps.apply(d,new JSONObject().put("type","set_transform").put("layerId","layer_1").put("transform",new JSONObject().put("rotation",-7).put("scaleX",.9).put("scaleY",1.1).put("opacity",.63)));}
   renderers[0]=new SketchFrameRenderer(context(),plain);renderers[1]=new SketchFrameRenderer(context(),grid);Bitmap a=renderers[0].render(0,false),b=renderers[1].render(0,false);try{SketchPaintMeshTest.assertNativePixels(a,b,evidence,"native");}finally{a.recycle();b.recycle();}for(SketchFrameRenderer r:renderers)r.prepareRasterResources(128,0);
  });Bitmap a=Bitmap.createBitmap(256,512,Bitmap.Config.ARGB_8888),b=Bitmap.createBitmap(256,512,Bitmap.Config.ARGB_8888);try{renderers[0].draw(new Canvas(a),0,false);renderers[1].draw(new Canvas(b),0,false);SketchPaintMeshTest.assertNativePixels(a,b,evidence,"cached");}finally{a.recycle();b.recycle();}}finally{for(SketchFrameRenderer r:renderers)if(r!=null)r.close();}
 }
 @Test @Config(sdk={29,33}) public void movedFocusedTexturePickingArchiveUndoAndStoredKeysRetainTheSourceInterval()throws Exception{worker(()->{
  JSONObject d=fixture(),prepared=prepare(d,true),operation=prepared.getJSONObject("operation"),mesh=operation.getJSONObject("patch").getJSONObject("paintMesh");String id=d.getString("id"),sourceSha=SketchDocument.object(d,"paint").getJSONObject("paint").getString("sha256");JSONArray regular=new JSONArray(mesh.getJSONArray("points").toString()),moved=new JSONArray(regular.toString());for(int i=0;i<moved.length();i++){JSONArray p=moved.getJSONArray(i);p.put(0,p.getDouble(0)-.25).put(1,p.getDouble(1)+.125);}mesh.put("keys",new JSONArray().put(new JSONObject().put("frame",0).put("points",regular).put("interpolation","hold")).put(new JSONObject().put("frame",4).put("points",moved).put("interpolation","hold")));
  SketchPaintMeshTest.edit(context(),id,4,"grid",new JSONArray().put(operation));d=load(id);JSONObject selected=SketchDocument.object(d,"paint");assertEquals(sourceSha,selected.getJSONObject("paint").getString("sha256"));double[] uv=SketchPaintMesh.sourceAt(selected,4,.45,.50);assertNotNull(uv);assertEquals(.7,uv[0],1e-12);assertEquals(.375,uv[1],1e-12);
  JSONObject expected=SketchDocument.copy(d);SketchDocument.object(expected,"paint").remove("paintMesh");SketchDocument.object(expected,"paint").getJSONObject("transform").put("x",-.25).put("y",.125);
  java.io.File evidence=new java.io.File("build/native-focused-mesh-translation/"+java.util.UUID.randomUUID());assertTrue(evidence.mkdirs());try(SketchFrameRenderer actual=new SketchFrameRenderer(context(),d);SketchFrameRenderer reference=new SketchFrameRenderer(context(),expected)){actual.enableImageSelections();Bitmap a=reference.render(4,false),b=actual.render(4,false);try{SketchPaintMeshTest.assertNativePixels(a,b,evidence,"translated");}finally{a.recycle();b.recycle();}assertEquals("paint",SketchFrameRenderer.hitTest(d,4,.45,.50,.001,actual.imageSelections()));assertNull(SketchFrameRenderer.hitTest(d,4,.45,.565,.001,actual.imageSelections()));assertNull(SketchFrameRenderer.hitTest(d,4,.7,.44,.001,actual.imageSelections()));}
  JSONObject staticPaint=SketchPaintMesh.sampled(selected,4);assertEquals(SketchDocument.canonical(mesh.getJSONArray("sourceRect")),SketchDocument.canonical(staticPaint.getJSONObject("paintMesh").getJSONArray("sourceRect")));
  SketchPaintArchive.Prepared archive=SketchPaintArchive.prepare(context(),new JSONObject().put("sketchId",id).put("expectedRevision",5).put("operationId","archive"));JSONObject restored=SketchPaintArchive.restoreFile(context(),archive.file,SketchProjectStore.fileHash(archive.file),"restore_focus","Focused restore"),restoredPaint=SketchDocument.object(load(restored.getString("sketchId")),"paint");assertEquals(SketchDocument.canonical(mesh),SketchDocument.canonical(restoredPaint.getJSONObject("paintMesh")));
  String component="focus_component_"+java.util.UUID.randomUUID(),target="focus_target_"+java.util.UUID.randomUUID();SketchComponentLibrary.execute(context(),"sketch_component_save",new JSONObject().put("componentId",component).put("sketchId",id).put("expectedRevision",5).put("operationId","save").put("name","Owned focused part").put("category","hand").put("frameIndex",4));SketchEditOps.execute(context(),"sketch_create",new JSONObject().put("sketchId",target).put("operationId","create").put("width",256).put("height",512).put("frameCount",8));SketchComponentLibrary.execute(context(),"sketch_component_apply",new JSONObject().put("componentId",component).put("sketchId",target).put("expectedRevision",1).put("operationId","place").put("frameIndex",0).put("exposure",8));JSONObject placed=load(target).getJSONArray("layers").getJSONObject(1).getJSONArray("objects").getJSONObject(0);assertEquals(SketchDocument.canonical(staticPaint.getJSONObject("paintMesh")),SketchDocument.canonical(placed.getJSONObject("paintMesh")));assertEquals(sourceSha,placed.getJSONObject("paint").getString("sha256"));
  SketchEditOps.execute(context(),"sketch_undo",new JSONObject().put("sketchId",id).put("expectedRevision",5).put("operationId","undo"));assertFalse(SketchDocument.object(load(id),"paint").has("paintMesh"));SketchEditOps.execute(context(),"sketch_redo",new JSONObject().put("sketchId",id).put("expectedRevision",6).put("operationId","redo"));assertEquals(sourceSha,SketchDocument.object(load(id),"paint").getJSONObject("paint").getString("sha256"));
 });}
 @Test @Config(sdk={29,33}) public void integerCropPrecedesCacheResizeAndUsesTheSameInverseTriangles()throws Exception {worker(()->{
  Bitmap source=Bitmap.createBitmap(256,256,Bitmap.Config.ARGB_8888);int[] pixels=new int[256*256];for(int y=0;y<256;y++)for(int x=0;x<256;x++)pixels[y*256+x]=Color.rgb(x,y,0);source.setPixels(pixels,0,256,0,0,256,256);
  JSONObject mesh=SketchPaintMesh.focused(3,4,new JSONArray("[17,23,218,237]"),256,256),object=new JSONObject().put("kind","paint").put("bounds",new JSONObject("{x:0,y:0,width:1,height:1}")).put("paint",new JSONObject().put("width",256).put("height",256)).put("paintMesh",mesh);JSONArray points=mesh.getJSONArray("points");for(int i=0;i<points.length();i++){JSONArray p=points.getJSONArray(i);p.put(0,p.getDouble(0)+.08*p.getDouble(1));p.put(1,p.getDouble(1)*.85+.03);}SketchPaintMesh.validate(object,1);
  java.io.File evidence=new java.io.File("build/native-focused-integer-crop/"+java.util.UUID.randomUUID());assertTrue(evidence.mkdirs());try{for(int edge:new int[]{0,91}){Bitmap texture=SketchPaintMesh.focusedTexture(source,mesh,edge),target=Bitmap.createBitmap(256,256,Bitmap.Config.ARGB_8888),oracle=Bitmap.createBitmap(256,256,Bitmap.Config.ARGB_8888);try{
   Bitmap cropped=Bitmap.createBitmap(source,17,23,201,214);Bitmap resized=edge==0?cropped:Bitmap.createScaledBitmap(cropped,texture.getWidth(),texture.getHeight(),true);try{SketchPaintMeshTest.assertNativePixels(resized,texture,evidence,"exact-crop-before-cache-"+edge);}finally{if(resized!=cropped)resized.recycle();cropped.recycle();}
   SketchPaintMesh.drawGrid(new Canvas(target),texture,mesh,SketchPaintMesh.vertices(object,0,256,256),new Paint(Paint.FILTER_BITMAP_FLAG));Matrix mapping=new Matrix();mapping.setValues(new float[]{201f/texture.getWidth(),.08f*214/texture.getHeight(),17+.08f*23,0,.85f*214/texture.getHeight(),.85f*23+.03f*256,0,0,1});new Canvas(oracle).drawBitmap(texture,mapping,new Paint(Paint.FILTER_BITMAP_FLAG));
   for(int[] probe:new int[][]{{70,70},{140,110},{180,170}}){double[] uv=SketchPaintMesh.sourceAt(object,0,(probe[0]+.5)/256d,(probe[1]+.5)/256d);assertNotNull(uv);int actual=target.getPixel(probe[0],probe[1]);assertEquals("Integer-cropped texture must match native bitmap sampling",oracle.getPixel(probe[0],probe[1]),actual);assertEquals(255,Color.alpha(actual));assertEquals("Full-source U with pixel centres and cache quantization",uv[0]*256-.5,Color.red(actual),1.5);assertEquals("Full-source V with pixel centres and cache quantization",uv[1]*256-.5,Color.green(actual),1.5);}
  }finally{texture.recycle();target.recycle();oracle.recycle();}}}finally{source.recycle();}
 });}
 @Test @Config(sdk={29,33}) public void bentSemitransparentTrianglesHaveNoDuplicateInteriorAlphaSeams()throws Exception {worker(()->{
  Bitmap source=Bitmap.createBitmap(256,256,Bitmap.Config.ARGB_8888),target=Bitmap.createBitmap(256,256,Bitmap.Config.ARGB_8888);source.eraseColor(0x80204060);try{JSONObject mesh=SketchPaintMesh.focused(16,16,new JSONArray("[0,0,256,256]"),256,256),object=new JSONObject().put("paint",new JSONObject().put("width",256).put("height",256)).put("paintMesh",mesh);JSONArray points=mesh.getJSONArray("points");for(int i=0;i<points.length();i++){JSONArray p=points.getJSONArray(i);p.put(0,p.getDouble(0)+.03*Math.sin(p.getDouble(1)*Math.PI));}SketchPaintMesh.drawGrid(new Canvas(target),source,mesh,SketchPaintMesh.vertices(object,0,256,256),new Paint(Paint.FILTER_BITMAP_FLAG));for(int y=16;y<240;y++)for(int x=24;x<232;x++)assertEquals("Interior triangles must apply source alpha once at "+x+","+y,128,Color.alpha(target.getPixel(x,y)));}finally{target.recycle();source.recycle();}
 });}
 @Test @Config(sdk={29,33}) public void actualBentRendererPreparesBoundedCachedTexturesAndFullSourceAlphaPicking()throws Exception {
  final SketchFrameRenderer[] renderer=new SketchFrameRenderer[1];final JSONObject[] stored=new JSONObject[1];try{worker(()->{JSONObject d=fixture(),op=prepare(d,true).getJSONObject("operation"),mesh=op.getJSONObject("patch").getJSONObject("paintMesh");JSONArray regular=new JSONArray(mesh.getJSONArray("points").toString()),points=mesh.getJSONArray("points");for(int i=0;i<points.length();i++){JSONArray p=points.getJSONArray(i);p.put(0,p.getDouble(0)+.08*p.getDouble(1));p.put(1,p.getDouble(1)*.85+.03);}mesh.put("points",regular).put("keys",new JSONArray().put(new JSONObject().put("frame",0).put("points",regular).put("interpolation","hold")).put(new JSONObject().put("frame",4).put("points",points).put("interpolation","hold")));String id=d.getString("id"),source=SketchDocument.object(d,"paint").getJSONObject("paint").getString("sha256");SketchPaintMeshTest.edit(context(),id,4,"bend",new JSONArray().put(op));stored[0]=load(id);assertEquals(source,SketchDocument.object(stored[0],"paint").getJSONObject("paint").getString("sha256"));renderer[0]=new SketchFrameRenderer(context(),stored[0]);renderer[0].enableImageSelections();Bitmap actual=renderer[0].render(4,false);try{assertTrue(Color.alpha(actual.getPixel(187,178))>0);assertEquals(0,Color.alpha(actual.getPixel(188,207)));}finally{actual.recycle();}renderer[0].prepareRasterResources(128,4);renderer[0].prepareRasterResources(128);assertTrue(renderer[0].preparedRasterBytes()<=12L*1024*1024);assertTrue(renderer[0].preparedSelectionBytes()<=8L*1024*1024);assertEquals("paint",SketchFrameRenderer.hitTest(stored[0],4,.73,.34875,.001,renderer[0].imageSelections()));assertNull(SketchFrameRenderer.hitTest(stored[0],4,.7352,.404,.001,renderer[0].imageSelections()));assertNull(SketchFrameRenderer.hitTest(stored[0],4,.3,.7,.001,renderer[0].imageSelections()));});Bitmap cached=Bitmap.createBitmap(256,512,Bitmap.Config.ARGB_8888);try{renderer[0].draw(new Canvas(cached),4,false);assertTrue(Color.alpha(cached.getPixel(187,178))>0);assertEquals(0,Color.alpha(cached.getPixel(188,207)));}finally{cached.recycle();}}finally{if(renderer[0]!=null)renderer[0].close();}
 }
 @Test public void alphaOneAtSourceEdgesKeepsTheFullSamplingIntervalAndCopyPixels()throws Exception {worker(()->{
  Bitmap source=Bitmap.createBitmap(256,512,Bitmap.Config.ARGB_8888);source.setPixel(0,0,0x01ffffff);source.setPixel(255,511,0x24ff0000);source.setPixel(180,256,0x25ff0000);try{JSONArray bounds=SketchPaintMeshPrepare.supportRectangle(source);assertEquals("[0,0,256,512]",bounds.toString());JSONObject mesh=SketchPaintMesh.focused(4,8,bounds,256,512);Bitmap texture=SketchPaintMesh.focusedTexture(source,mesh,0);try{java.io.File evidence=new java.io.File("build/native-focused-alpha-support/"+java.util.UUID.randomUUID());assertTrue(evidence.mkdirs());SketchPaintMeshTest.assertNativePixels(source,texture,evidence,"full-alpha-support");}finally{texture.recycle();}Thread.currentThread().interrupt();try{assertThrows(java.io.InterruptedIOException.class,()->SketchPaintMesh.focusedTexture(source,mesh,128));}finally{Thread.interrupted();}assertFalse(source.isRecycled());assertEquals(0x01ffffff,source.getPixel(0,0));}finally{source.recycle();}
 });}
 @Test public void excludedAlphaAndMalformedSourceRectanglesRejectWithoutPublishing()throws Exception{worker(()->{
  JSONObject d=fixture(),prepared=prepare(d,true),op=prepared.getJSONObject("operation"),mesh=op.getJSONObject("patch").getJSONObject("paintMesh");String id=d.getString("id"),before=SketchDocument.canonical(d);mesh.put("sourceRect",new JSONArray("[150,180,190,240]"));assertThrows(IllegalArgumentException.class,()->SketchPaintMeshTest.edit(context(),id,4,"bad",new JSONArray().put(op)));assertEquals(before,SketchDocument.canonical(load(id)));
  JSONObject malformed=SketchDocument.copy(d);SketchDocument.object(malformed,"paint").put("paintMesh",mesh);try(SketchFrameRenderer renderer=new SketchFrameRenderer(context(),malformed)){assertThrows(IllegalArgumentException.class,()->renderer.render(0,false));}
  for(String rect:new String[]{"null","[0,0,200]","[0.5,0,200,300]","[0,0,257,300]","[200,0,100,300]","[0,0,1e30,300]","[0,0,200,\"300\"]"}){JSONObject candidate=SketchDocument.copy(d),paint=SketchDocument.object(candidate,"paint");JSONObject invalid=new JSONObject(mesh.toString());invalid.put("sourceRect",new org.json.JSONTokener(rect).nextValue());paint.put("paintMesh",invalid);assertThrows(Exception.class,()->SketchDocument.validate(candidate));}
 });}
}
